#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""FEYZULLAH AKILLI ÇİFTLİK V34.3 — tek dosyalık Render dağıtımı / Medya Arama Güçlendirme.

Render Build Command:
  python FEYZULLAH_AKILLI_CIFTLIK_TEK_DOSYA_RENDER_V34_2_MEDYA_PLUS.py --prepare && pip install -r requirements.txt
Render Start Command:
  uvicorn main:app --host 0.0.0.0 --port $PORT
"""
import argparse, base64, hashlib, io, zipfile
from pathlib import Path, PurePosixPath

_ARCHIVE_SHA256 = "e547169753b38741371b3f43de3cdb7f8de7223acccbc6d4025a3e5f085b8891"
_ARCHIVE_B64 = r"""

"""

def prepare():
    payload = base64.b64decode(_ARCHIVE_B64)
    actual = hashlib.sha256(payload).hexdigest()
    if actual != _ARCHIVE_SHA256:
        raise SystemExit("Paket doğrulaması başarısız: SHA256 uyuşmuyor.")
    root = Path.cwd().resolve()
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        for info in archive.infolist():
            rel = PurePosixPath(info.filename)
            if rel.is_absolute() or ".." in rel.parts:
                raise SystemExit("Güvensiz arşiv yolu reddedildi.")
            target = (root / Path(*rel.parts)).resolve()
            if root not in target.parents and target != root:
                raise SystemExit("Arşiv hedef dizinin dışına çıkıyor.")
        archive.extractall(root)
    print("V34.3 proje dosyaları hazırlandı; medya kaynakları, arama kalitesi ve hata yönetimi güçlendirildi.")
    print("Sonraki adım: pip install -r requirements.txt")
    print("Başlatma: uvicorn main:app --host 0.0.0.0 --port $PORT")

def main():
    parser = argparse.ArgumentParser(description="FEYZULLAH AKILLI ÇİFTLİK V34.3 Medya Arama Güçlendirme hazırlayıcı")
    parser.add_argument("--prepare", action="store_true", help="Gömülü proje dosyalarını çalışma klasörüne çıkar")
    args = parser.parse_args()
    if args.prepare:
        prepare()
    else:
        parser.print_help()

if __name__ == "__main__":
    main()
